SELECT

FROM news


        AND wm_user_id = #{q.wmUserId}


        AND status = #{q.status}


        AND channel_id = #{q.channelId}


        AND title LIKE CONCAT('%', #{q.keyword}, '%')


        AND create_time >= #{q.startDate}


        AND create_time <= #{q.endDate}




        ORDER BY views DESC, id DESC


        ORDER BY update_time DESC, id DESC

SELECT channel_id AS channelId, COUNT(*) AS total FROM news WHERE status = 2 AND channel_id IN
#{id}
GROUP BY channel_id
